          mc('On which interval does h(t) = 12 + 10sin(πt/15) increase?', ['0 < t < 7.5', '7.5 < t < 22.5', '15 < t < 30', '0 < t < 15'], note='Rises to the maximum at t = 7.5.'),
          mc('How can the frequency be read from the graph of a periodic function?', [
                        'Find the length of one cycle (the period) and take its reciprocal, the number of cycles per unit of the input.',
                        'Read the maximum height of the graph, which is the number of cycles per unit of the input.',
                        'Count the number of times the graph crosses the x-axis in the window shown; that count is the frequency.',
                        'Find half the difference between the maximum and the minimum, which is the number of cycles per unit.'],
                       note='Frequency = 1/period. The others give the maximum, a count that depends on the midline, or the amplitude.'),
